from base.exceptions import EntityBadRequestErrorfrom entities.container import Container, ContainerTypefrom entities.topic_offer import TopicOffer, TopicOfferStatusfrom helpers.search import Paginationfrom schemas.topic import AddTopicByOffer, CreateTopicfrom services.container import ContainerServicefrom services.topic_offer import TopicOfferServicefrom sqlalchemy.ext.asyncio import AsyncSessionfrom utils.container import ContainerSearchParamsfrom utils.post import generate_slugclass TopicService(ContainerService):    def __init__(self, session: AsyncSession):        super().__init__(session)        self.offer_service = TopicOfferService(session)    async def create_topic(            self,            topic: CreateTopic,            author_id: int,    ) -> Container:        topic.slug = generate_slug(topic.slug)        await self.check_already_exists(slug=topic.slug, type=ContainerType.topic)        topic = await self.create_item(            **topic.dict(),            type=ContainerType.topic,            author_id=author_id        )        return await self.repository.get_full_container(topic.id)    async def search_topic(            self, pagination: Pagination,            search: ContainerSearchParams    ) -> list[Container]:        return await self.search_container(            type_=ContainerType.topic, search=search, pagination=pagination        )    async def create_topic_from_offer(            self,            topic_offer: TopicOffer,            process: AddTopicByOffer,            process_user_id: int    ) -> TopicOffer:        if topic_offer.status != TopicOfferStatus.PENDING:            raise EntityBadRequestError(                "offer-Тема", f"Предложенная тема уже имеет статус {topic_offer.status}"            )        await self.offer_service.update_item(            topic_offer.id,            status=process.status,            process_user_id=process_user_id        )        if process.status == TopicOfferStatus.APPROVE:            slug = generate_slug(process.slug)            title = process.title or topic_offer.title            description = process.description or topic_offer.description            topic = CreateTopic(                title=title,                description=description,                slug=slug            )            release_topic = await self.create_topic(                topic=topic, author_id=topic_offer.author_id            )            await self.offer_service.update_item(                topic_offer.id,                release_topic_id=release_topic.id            )        return topic_offer